from zipfile import ZipFile, ZIP_DEFLATED
from pathlib import Path
from xml.sax.saxutils import escape
import re

IDENT = '[Student name]  |  [SRN]  |  [Programme, semester]'
PROJECT_IDENT = 'Vignesh V Hegde  |  R23EJ138  |  CSIT C'

def build(src, dst, replacements):
    with ZipFile(src) as zin, ZipFile(dst, 'w', ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            data = zin.read(item.filename)
            m = re.fullmatch(r'ppt/slides/slide(\d+)\.xml', item.filename)
            if m:
                mapping = replacements.get(int(m.group(1)), {})
                text = data.decode('utf-8')
                for old, new in mapping.items():
                    text = text.replace('>' + escape(old) + '<', '>' + escape(new) + '<')
                data = text.encode('utf-8')
            zout.writestr(item, data)

